-- Retain original post status/date and reference restrictions; add v2 explicit asset manifest.
ALTER POLICY assets_public_read ON public.post_assets USING ((EXISTS ( SELECT 1
   FROM posts p
  WHERE ((p.id = post_assets.post_id) AND (p.status = 'published'::text) AND ((p.published_at <= now()) OR ((p.published_at IS NULL) AND (p.slug = ANY (ARRAY['food-label-guide'::text, 'gmk-material'::text, 'what-is-gmk'::text, 'human-study-and-approval'::text])) AND (((p.details -> 'migration'::text) ->> 'source'::text) = 'static'::text) AND (((p.details -> 'migration'::text) ->> 'slug'::text) = p.slug) AND (((p.details -> 'migration'::text) ->> 'date_unknown'::text) = 'true'::text))) AND ((p.thumbnail_path = post_assets.storage_path) OR ((p.content -> 'blocks'::text) @> jsonb_build_array(jsonb_build_object('type', 'image', 'path', post_assets.storage_path))) OR ((p.content -> 'blocks'::text) @> jsonb_build_array(jsonb_build_object('type', 'gallery', 'images', jsonb_build_array(jsonb_build_object('path', post_assets.storage_path))))) OR ((p.content -> 'asset_paths') ? post_assets.storage_path) OR ((p.details -> 'attachments'::text) @> jsonb_build_array(post_assets.storage_path)))))));
